:root {
  --ink: #26384a;
  --paper: #fffdf7;
  --mist: #e5f1ef;
  --teal: #24766e;
  --line: #b9d5d0;
}

.tuning-card {
  box-sizing: border-box;
  width: 460px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 14px;
}

.card-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 18px;
  background: var(--mist);
}

.note-icon {
  display: inline-block;
  width: 38px;
  height: 38px;
  box-sizing: border-box;
  padding-top: 6px;
  color: var(--paper);
  background: var(--teal);
  border-radius: 50%;
  text-align: center;
  font-size: 22px;
  line-height: 26px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--teal);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.2px;
}

h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.1;
}

.appointment {
  display: flex;
  justify-content: space-between;
  padding: 14px 18px;
  font-size: 14px;
}

.card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 18px;
  border-top: 1px solid var(--line);
  font-size: 12px;
}

.card-footer b {
  color: var(--teal);
  font-size: 11px;
  letter-spacing: 0.7px;
}
